        if self.type == LogicType.AND:
            return f"({' ∧ '.join(map(str, self.children))})"
        if self.type == LogicType.OR:
            return f"({' ∨ '.join(map(str, self.children))})"
        if self.type == LogicType.FORALL:
            return f"∀{self.variable}({self.children[0]})"
        if self.type == LogicType.EXISTS:
            return f"∃{self.variable}({self.children[0]})"
        return "Unknown"